"""Offline protocol integration cases; edits are prescribed, not generated by a model."""

import hashlib
import importlib.util
import json
import sys
import tempfile
from pathlib import Path

from repo_agent.engine import Engine
from repo_agent.store import Store

ROOT = Path(__file__).resolve().parents[1]


class FixtureProvider:
    def __init__(self, case):
        self.case = case
        self.index = 0

    def complete(self, messages, tools):
        c = self.case
        i = self.index
        self.index += 1
        results = [json.loads(m["content"]) for m in messages if m["role"] == "tool"]
        if i == 0:
            name, args = (
                "load_skill",
                {
                    "name": "repo-exploration"
                    if c.get("readonly")
                    else "feature-development"
                    if c["category"] == "feature"
                    else "bug-diagnosis"
                },
            )
        elif i == 1:
            name, args = "list_files", {}
        elif i == 2 and c["before"]:
            name, args = "read_file", {"path": c["path"]}
        elif c.get("readonly"):
            return {
                "content": "Fixture inspected the file; this is not a model-generated explanation."
            }, {}
        elif not any("proposal_id" in x for x in results):
            name, args = (
                "propose_edit",
                {"path": c["path"], "old_text": c["old"], "new_text": c["new"]},
            )
        elif not any(x.get("status") == "applied" or "error" in x for x in results):
            name, args = (
                "apply_edit",
                {
                    "proposal_id": next(
                        x["proposal_id"] for x in results if "proposal_id" in x
                    )
                },
            )
        elif c.get("deny"):
            return {"content": "Human rejected the change; file preserved."}, {}
        elif not any("exit_code" in x for x in results):
            name, args = "run_tests", {"runner": "unittest"}
        else:
            return {
                "content": "Offline fixture complete. See independent checker result."
            }, {}
        return {
            "content": "",
            "tool_calls": [
                {
                    "id": f"fixture-{i}",
                    "type": "function",
                    "function": {"name": name, "arguments": json.dumps(args)},
                }
            ],
        }, {}


def execute(case):
    with tempfile.TemporaryDirectory() as tmp:
        base = Path(tmp)
        root = base / "workspace"
        root.mkdir()
        if case["before"]:
            (root / case["path"]).write_text(case["before"], encoding="utf-8")
        (root / "tests").mkdir()
        header = "import importlib.util\nfrom pathlib import Path\nimport unittest\nspec=importlib.util.spec_from_file_location('logic',Path(__file__).resolve().parents[1]/'logic.py')\nm=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)\n"
        (root / "tests/test_logic.py").write_text(
            header
            + "class Check(unittest.TestCase):\n    def test_behavior(self):\n        "
            + case["check"]
            + "\n",
            encoding="utf-8",
        )
        store = Store(base / "state")
        s = store.create(root, case["task"])
        engine = Engine(store, FixtureProvider(case), backend="trusted-local")
        for _ in range(5):
            s = engine.run(s["id"])
            if s["status"] != "waiting_approval":
                break
            store.resolve(s["id"], s["pending_approval"], not case.get("deny", False))
        spec = importlib.util.spec_from_file_location("checked", root / case["path"])
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        # This expected behavior lives outside the tool workspace and cannot be edited by the agent.
        exec(case["check"], {"m": module})
        if case.get("deny"):
            assert (root / case["path"]).read_text(encoding="utf-8") == case["before"]
        else:
            if not case.get("readonly"):
                assert s["verification"] == "passed"
        assert s["status"] == "completed", s
        events = store.events(s["id"])
        store.db.close()
        return dict(
            id=case["id"],
            category=case["category"],
            passed=True,
            steps=s["steps"],
            verification=s["verification"],
            tools=[e["data"]["tool"] for e in events if e["kind"] == "tool_result"],
        )


def main():
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8")
    dataset = ROOT / "evaluation/tasks.jsonl"
    cases = [json.loads(x) for x in dataset.read_text(encoding="utf-8").splitlines()]
    results = []
    for case in cases:
        try:
            results.append(execute(case))
        except Exception as exc:
            results.append(dict(id=case["id"], passed=False, error=str(exc)[:300]))
    report = dict(
        mode="offline_scripted_integration",
        model=None,
        scope="预设工具调用和补丁；验证执行、审核、恢复和验收机制，不衡量真实模型修复能力",
        dataset_sha256=hashlib.sha256(
            dataset.read_text(encoding="utf-8").encode("utf-8")
        ).hexdigest(),
        total=len(results),
        passed=sum(x["passed"] for x in results),
        results=results,
    )
    (ROOT / "evaluation/offline-results.json").write_text(
        json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8"
    )
    print(json.dumps(report, ensure_ascii=False, indent=2))
    return 0 if report["passed"] == report["total"] else 1


if __name__ == "__main__":
    sys.exit(main())
